'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:2}).format(v)+' Kč';
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const dateKey=(d=new Date())=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Prague'}).format(d);
const now=dateKey();
const uid=()=>crypto.randomUUID();
const full=e=>e?e.first+' '+e.last:'Archivovaný zaměstnanec';
const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString('cs-CZ',{day:'numeric',month:'long',year:'numeric'});
let state={employees:[],foods:[],packs:[],shifts:[],categories:[],positions:[],records:[],audit:[],revision:0,version:1};
let setupSecret=new URLSearchParams(location.hash.slice(1)).get('setup')||'';
if(setupSecret)history.replaceState(null,'',location.pathname+location.search);
let setupRequired=false,saving=false;
async function api(path,body){
 const res=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});
 const data=await res.json();if(!res.ok){const e=new Error(data.error||'Požadavek se nezdařil.');e.status=res.status;throw e;}return data;
}
async function loadSession(){try{const data=await api('/api/session');setupRequired=!!data.setupRequired;actor=data.actor;if(data.state){state=data.state;selectedShift=activeShifts()[0]?.id;profileId=actor.id==='admin'?state.employees[0]?.id:actor.id;if(!canWrite())page='profile';}render();}catch(e){if(e.status===401){actor=null;login();toast(e.message);return;}$('#app').innerHTML='<div class="empty"><strong>Aplikace se nepodařila načíst.</strong><p>Zkontrolujte připojení a obnovte stránku.</p></div>';toast(e.message);}}
async function doLogout(){try{await api('/api/logout',{});cart={};packcart={};actor=null;state={employees:[],foods:[],packs:[],shifts:[],categories:[],positions:[],records:[],audit:[],revision:0};login();}catch(e){toast(e.message);}}
let actor=null, page='entry', selectedEmployee='', selectedShift=state.shifts[0]?.id, selectedDate=now, category='Oblíbené', cart={}, packcart={}, employeeQuery='',foodQuery='',listQuery='',month=now.slice(0,7), reportDate=now, profileId=state.employees[0]?.id, editId=null;
const activeEmployees=()=>state.employees.filter(e=>e.active), activeFoods=()=>state.foods.filter(e=>e.active), activePacks=()=>state.packs.filter(e=>e.active), activeShifts=()=>state.shifts.filter(e=>e.active);
const isAdmin=()=>actor?.id==='admin';
const canWrite=()=>isAdmin()||!!state.employees.find(e=>e.id===actor?.id&&e.active&&e.writer);
const employee=id=>state.employees.find(e=>e.id===id);
const actorName=()=>isAdmin()?(actor.displayName||'Administrátor'):full(employee(actor?.id));
function audit(action,target,before='',after=''){return{id:uid(),at:new Date().toISOString(),actor:actorName(),actorId:actor?.id,action,target,before,after};}
async function change(mutator,log,accountPassword){
 if(saving){toast('Předchozí zápis se ještě ukládá.');return false;}
 saving=true;
 try{const next=structuredClone(state);mutator(next);const data=await api('/api/state',{state:next,revision:state.revision,...(accountPassword?{accountPassword}:{})});state=data.state;return true;
 }catch(e){if(e.status===409||e.status===403){try{state=(await api('/api/state')).state;if(!canWrite()){cart={};packcart={};selectedEmployee='';}if($('#modal').open)closeModal();render();}catch{}}if(e.status===401){actor=null;login();}toast(e.message);return false;
 }finally{saving=false;}
}
const cents=v=>Math.round((v+Number.EPSILON)*100)/100;
function calc(r){const meals=r.items.reduce((a,i)=>a+i.price*i.qty,0), own=r.packs.filter(p=>p.payer==='employee').reduce((a,p)=>a+p.price*p.qty,0), budget=r.packs.filter(p=>p.payer==='budget').reduce((a,p)=>a+p.price*p.qty,0), company=r.packs.filter(p=>p.payer==='company').reduce((a,p)=>a+p.price*p.qty,0);return{meals:cents(meals),own:cents(own),budget:cents(budget),company:cents(company),packs:cents(own+budget+company),covered:cents(Math.min(r.shift.limit,meals+budget)),due:cents(Math.max(0,cents(meals+budget)-r.shift.limit)+own)};}
const sum=(rs,key)=>rs.reduce((a,r)=>a+calc(r)[key],0);
const findDaily=()=>state.records.find(r=>r.employeeId===selectedEmployee&&r.date===selectedDate);
function currentShift(){return findDaily()?.shift||state.shifts.find(s=>s.id===selectedShift)||activeShifts()[0]||{id:'',name:'Bez směny',code:'—',limit:0};}
const pickedItems=()=>Object.entries(cart).filter(([,q])=>q>0).map(([id,qty])=>({...state.foods.find(f=>f.id===id),qty}));
const pickedPacks=()=>Object.entries(packcart).filter(([,q])=>q>0).map(([id,qty])=>({...state.packs.find(f=>f.id===id),qty}));
function combine(old,added){const out=old.map(i=>({...i}));for(const i of added){const existing=out.find(p=>p.id===i.id&&p.price===i.price&&p.payer===i.payer);if(existing)existing.qty+=i.qty;else out.push({...i});}return out;}
function projected(){const existing=findDaily();return{employeeId:selectedEmployee,date:selectedDate,shift:{...currentShift()},items:combine(existing?.items||[],pickedItems()),packs:combine(existing?.packs||[],pickedPacks())};}
function describe(r){if(!r)return'Žádný zápis';const c=calc(r);return `${fmtDate(r.date)} · ${r.shift.code} (${money(r.shift.limit)}) · ${r.items.map(i=>i.qty+'× '+i.name+' ('+money(i.price)+')').join(', ')||'bez jídel'}${r.packs.length?' · Obaly: '+r.packs.map(p=>p.qty+'× '+p.name+' ('+money(p.price)+', '+payerLabel(p.payer)+')').join(', '):''} · Doplatek ${money(c.due)}`;}
function payerLabel(p){return{company:'hradí podnik',budget:'z limitu směny',employee:'hradí zaměstnanec'}[p]||p;}
let toastTimeout;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function showModal(title,body){$('#modalbody').innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="iconbutton" data-action="close-modal" aria-label="Zavřít">✕</button></div>${body}`;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
const field=(label,input)=>`<label class="field">${esc(label)}${input.replace(/<(input|select|textarea)\b/,`<$1 aria-label="${esc(label)}"`)}</label>`;
const input=(name,value='',type='text',extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const option=(val,text,sel)=>`<option value="${esc(val)}" ${String(val)===String(sel)?'selected':''}>${esc(text)}</option>`;
function login(){const setup=setupRequired&&setupSecret;$('#app').innerHTML=`<div class="login"><section class="login-story"><a class="brand" href="#">${brand()}perso<span style="color:var(--lime)">.</span></a><div><h1>Dobré jídlo.<br>Čisté účty.<br><span>Bez papírování.</span></h1><p>Personální strava pod kontrolou. Jeden člověk zapíše směnu, každý má svůj přehled.</p><div class="login-preview"><div class="previewrow"><span class="avatar">✓</span><div><strong>Celá směna na jednom místě</strong><small>Jídla, příspěvky i doplatky. Přehledně.</small></div><span class="tick">${icon('check')}</span></div></div></div><div class="footer">${icon('shield')} Přehled pro zaměstnance. Klid pro provoz.</div></section><section class="loginform"><span class="demo-label">PERSONÁLNÍ STRAVOVÁNÍ</span><div class="label">VÍTEJTE V PERSO</div><h2>${setup?'Nastavte svůj provoz.':'Směna začíná tady.'}</h2><p>${setup?'Vytvořte si heslo administrátora. Přihlašovací jméno bude admin. Tento odkaz lze použít jen pro první nastavení.':'Přihlaste se ke svému účtu. Zápisy i přehledy najdete na jednom místě.'}</p>${setupRequired&&!setupSecret?'<div class="info">Provoz ještě není nastavený. Otevřete jednorázový odkaz pro první nastavení, který obdržel správce aplikace.</div>':`<form id="${setup?'setup-form':'loginform'}">${setup?field('Vaše jméno',input('name','','text','required maxlength="120" autocomplete="name"')):field('Uživatelské jméno',input('username','','text','required maxlength="50" autocomplete="username" autocapitalize="none"'))}${field(setup?'Nové heslo administrátora':'Heslo',input('password','','password',`required ${setup?'minlength="12"':''} maxlength="128" autocomplete="${setup?'new-password':'current-password'}"`))}${setup?field('Zopakovat heslo',input('confirm','','password','required minlength="12" maxlength="128" autocomplete="new-password"')):''}<button class="btn primary" type="submit">${setup?'Vytvořit provoz':'Přihlásit se'} ${icon('arrow')}</button></form>`}<p class="fine">${setup?'Zvolte vlastní heslo s alespoň 12 znaky.':'Zapomenuté heslo vám obnoví administrátor provozu.'}<br>Vaše záznamy se bezpečně ukládají do společné databáze.</p></section></div>`;}
function brand(){return`<span class="brandmark">${icon('food')}</span>`;}
const pages={entry:['Rychlý zápis','Zapište celou směnu. Bez zbytečného klikání.','grid'],employees:['Zaměstnanci','Váš tým, pracovní pozice a oprávnění k zápisu.','users'],menu:['Jídelníček','Vlastní kategorie, ceny a oblíbená jídla pro rychlý výběr.','food'],reports:['Měsíční přehledy','Každý den přehledně. Každý doplatek dohledatelný.','chart'],profile:['Osobní přehled','Vlastní historie a stravování pod kontrolou.','users'],audit:['Historie změn','Kdo, kdy a co změnil. Včetně původních hodnot.','clock'],settings:['Nastavení','Směny, příspěvky, obaly a pracovní pozice.','settings']};
function render(){if(!actor)return login();if(!isAdmin()&&!employee(actor.id)?.active){actor=null;return login();}if(!canWrite()&&page==='entry')page='profile';if(!isAdmin()&&['employees','menu','audit','settings','reports'].includes(page))page='profile';const e=employee(actor.id);const nav=(p,extra='')=>`<button class="${page===p?'active':''}" data-nav="${p}">${icon(pages[p][2])}${pages[p][0]}${extra}</button>`;$('#app').innerHTML=`<div class="shell"><div class="overlay" data-action="toggle-menu"></div><aside class="sidebar"><a class="brand" href="#" data-nav="${canWrite()?'entry':'profile'}">${brand()}perso<span style="color:var(--green)">.</span></a><div class="workspace"><span class="mini">⌂</span><div><strong>Moje restaurace</strong><small>Personální stravování</small></div>${icon('down')}</div><p class="navlabel">Hlavní menu</p><nav class="nav">${canWrite()?nav('entry'):''}${isAdmin()?nav('reports')+nav('employees',`<span class="count">${activeEmployees().length}</span>`)+nav('menu'):''}${nav('profile')}${isAdmin()?`<div style="height:12px"></div><p class="navlabel">Správa</p>${nav('audit')}${nav('settings')}`:''}</nav><div class="sidebar-bottom"><div class="tip"><strong>${icon('check')} Méně klikání, více času</strong>Vyberte člověka, přidejte jídlo a uložte. O příspěvek a doplatek se postará Perso.</div><div class="user"><span class="avatar green">${isAdmin()?'AD':esc(initials(full(e)))}</span><div><strong>${isAdmin()?esc(actor.displayName||'Administrátor'):esc(full(e))}</strong><small>${isAdmin()?'Správce provozu':e.writer?'Pověřený zápisem':esc(e.position)}</small></div><button class="iconbutton" data-action="logout" title="Odhlásit se" aria-label="Odhlásit se">${icon('exit')}</button></div></div></aside><main class="main"><header class="topbar"><button class="iconbutton mobile-toggle" data-action="toggle-menu" aria-label="Otevřít menu">${icon('menu')}</button><div class="breadcrumb">Moje restaurace <span>›</span> <b>${pages[page][0]}</b></div><div class="top-right"><span class="prototype">Sdílený provoz</span><button class="iconbutton" data-action="password" title="Změnit heslo" aria-label="Změnit heslo">${icon('settings')}</button><button class="btn light" data-action="logout" style="font-size:10px;min-height:30px;padding:7px 10px">Odhlásit se</button><span class="avatar green">${isAdmin()?'AD':esc(initials(full(e)))}</span></div></header><div class="content">${renderPage()}</div><div id="mobile-entrybar" class="mobile-entrybar">${mobileBar()}</div></main></div>`;bindEntryInputs();}
function heading(actions=''){return`<div class="heading"><div><h1>${pages[page][0]}</h1><p>${pages[page][1]}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,value,sub,ic,highlight=false){return`<div class="stat ${highlight?'highlight':''}"><label>${label}</label><span class="stat-icon">${icon(ic)}</span><div class="value">${value}</div><div class="sub">${sub}</div></div>`;}
function stats(rs){return`<div class="stats">${stat('Zapsaní zaměstnanci',new Set(rs.map(r=>r.employeeId)).size,'z '+activeEmployees().length+' aktivních zaměstnanců','users')}${stat('Cena jídel',money(sum(rs,'meals')),rs.reduce((a,r)=>a+r.items.reduce((n,i)=>n+i.qty,0),0)+' zapsaných porcí','food')}${stat('Příspěvek podniku',money(sum(rs,'covered')),'čerpání limitů směn','shield')}${stat('Doplatky zaměstnanců',money(sum(rs,'due')),'včetně obalů hrazených zaměstnanci','chart',true)}</div>`;}
function renderPage(){switch(page){case'entry':return entry();case'employees':return employeesPage();case'menu':return menuPage();case'reports':return reportsPage();case'profile':return profilePage();case'audit':return auditPage();case'settings':return settingsPage();}}
function entry(){const rs=state.records.filter(r=>r.date===selectedDate);const shift=currentShift(),previous=findDaily();return heading(`<button class="btn" data-action="today">Dnes</button><label class="field"><input id="entrydate" type="date" value="${selectedDate}" aria-label="Datum zápisu"></label>`)+stats(rs)+`<div class="entry-layout"><section class="panel"><div class="panelhead"><h2>${icon('plus')} Nový zápis</h2><span class="eyebrow">${esc(new Date(selectedDate+'T12:00:00').toLocaleDateString('cs-CZ',{weekday:'long',day:'numeric',month:'long'}))}</span></div><div class="entrybody"><div class="form-top"><div><div class="step"><span class="num">1</span> Zaměstnanec</div><div class="searchwrap">${icon('search')}<input class="search" id="employee-search" placeholder="Hledat jméno…" value="${esc(employeeQuery)}" autocomplete="off" aria-label="Vyhledat zaměstnance"></div></div><div><div class="step"><span class="num">2</span> Směna a příspěvek</div><label class="field"><select id="shift-select" ${previous?'disabled':''} aria-label="Směna">${previous?option(shift.id,shift.code+' · '+shift.name+' / '+money(shift.limit),shift.id):activeShifts().map(s=>option(s.id,s.code+' · '+s.name+' / '+money(s.limit),selectedShift)).join('')}</select></label></div></div><div class="employee-picker" id="employee-picker">${employeeChips()}</div><div class="step"><span class="num">3</span> Co si dá k jídlu?</div><div class="searchwrap">${icon('search')}<input class="search" id="food-search" placeholder="Najít jídlo v jídelníčku…" value="${esc(foodQuery)}" autocomplete="off" aria-label="Vyhledat jídlo"></div><div class="tabs" id="food-tabs">${foodTabs()}</div><div class="foods" id="foods">${foodCards()}</div><div class="packaging"><div class="step">${icon('box')} Přidat obaly <span class="muted" style="font-weight:400;margin-left:auto;font-size:10px">Volitelné</span></div><div class="packgrid" id="packgrid">${packButtons()}</div></div></div></section><aside class="summary"><div class="panel"><div class="panelhead"><h2>Souhrn zápisu</h2><span class="eyebrow">${icon('food')}</span></div><div id="summary-inner" class="summary-inner">${summary()}</div></div><div class="note">${icon('shield')} Každý uložený zápis má svého autora. Změny jsou dohledatelné v historii administrátora.</div></aside></div><section class="panel daily"><div class="panelhead"><h2>Zápisy za tento den <span class="badge">${rs.length}</span></h2><span class="eyebrow">${fmtDate(selectedDate)}</span></div>${recordsTable(rs)}</section><p class="bottomnote">Perso · dobré jídlo, čisté účty. &nbsp; Změny se ukládají do společné databáze.</p>`;}
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function employeeChips(){const es=activeEmployees().filter(e=>norm(full(e)).includes(norm(employeeQuery)));return es.length?es.map(e=>`<button class="person-chip ${selectedEmployee===e.id?'selected':''}" data-employee="${e.id}" aria-pressed="${selectedEmployee===e.id}"><span class="avatar ${e.id==='e0'?'green':''}">${esc(initials(full(e)))}</span>${esc(full(e))}</button>`).join(''):`<span class="muted" style="font-size:11px;padding:10px">Žádný zaměstnanec neodpovídá hledání.</span>`;}
function foodTabs(){return['Oblíbené',...state.categories,'Vše'].map(c=>`<button class="tab ${category===c?'active':''}" data-category="${esc(c)}">${c==='Oblíbené'?'☆ ':''}${esc(c)}</button>`).join('');}
function foodCards(){const fs=activeFoods().filter(f=>norm(f.name).includes(norm(foodQuery))&&(foodQuery||category==='Vše'||category==='Oblíbené'&&f.favorite||f.category===category));return fs.length?fs.map(f=>`<button class="food ${cart[f.id]?'incart':''}" data-food="${f.id}" aria-label="Přidat ${esc(f.name)}, ${money(f.price)}"><span class="foodname">${esc(f.name)}</span>${f.favorite?'<span class="popular">★</span>':''}<span class="price">${money(f.price)}</span><span class="foodplus">${cart[f.id]||'+'}</span></button>`).join(''):`<div class="empty" style="grid-column:1/-1"><strong>Žádná jídla k zobrazení</strong>${category==='Oblíbené'?'Označte oblíbená jídla hvězdičkou v jídelníčku nebo zvolte jinou kategorii.':'Zkuste jinou kategorii nebo hledání.'}</div>`;}
function packButtons(){return activePacks().map(p=>`<button class="pack ${packcart[p.id]?'active':''}" data-pack="${p.id}" title="${esc(payerLabel(p.payer))}">${icon('box')}${esc(p.name)} · ${money(p.price)}${packcart[p.id]?`<em>${packcart[p.id]}×</em>`:'<span>+</span>'}</button>`).join('')||'<span class="muted">Obaly nejsou nastavené.</span>';}
function summary(){const e=employee(selectedEmployee),shift=currentShift(),existing=findDaily(),items=pickedItems(),packs=pickedPacks(),pr=projected(),c=calc(pr),oldDue=existing?calc(existing).due:0;const newMeals=items.reduce((a,i)=>a+i.price*i.qty,0),newPacks=packs.reduce((a,p)=>a+p.price*p.qty,0);return`<div class="summary-person"><span class="avatar green">${e?esc(initials(full(e))):'—'}</span><div><strong>${e?esc(full(e)):'Vyberte zaměstnance'}</strong><small>${e?esc(e.position)+' · ':''}${esc(shift.code)} · limit ${money(shift.limit)}</small></div></div>${items.length||packs.length?[...items.map(i=>cartRow(i,'food')),...packs.map(i=>cartRow(i,'pack'))].join(''):`<div class="emptycart">${icon('food')}<br>Na co je dnes chuť?<br>Jídlo přidáte jedním klepnutím.</div>`}<div class="totals"><div class="totalrow"><span>Jídla v tomto zápisu</span><b>${money(newMeals)}</b></div><div class="totalrow"><span>Obaly v tomto zápisu</span><b>${money(newPacks)}</b></div>${existing?`<div class="totalrow"><span>Již zapsaná jídla dnes</span><b>${money(calc(existing).meals)}</b></div>`:''}<div class="totalrow"><span>Čerpání limitu za den</span><b>${money(c.covered)} / ${money(shift.limit)}</b></div></div><div class="budget"><div class="bar"><span style="width:${shift.limit?Math.min(100,c.covered/shift.limit*100):0}%"></span></div><p>${c.covered<shift.limit?'Z limitu zbývá '+money(shift.limit-c.covered):'Limit směny je vyčerpán.'}${c.own?' Obaly mimo limit: '+money(c.own)+'.':''}</p></div><div class="due ${c.due?'over':''}"><span>Doplatek za celý den</span><strong>${money(c.due)}</strong></div>${existing?`<p class="info" style="font-size:10px;margin-bottom:14px">Dnešní zápis už existuje. Položky se přidají k němu; limit se znovu nepřiděluje. Doplatek navíc: <b>${money(c.due-oldDue)}</b>.</p>`:''}<button class="btn primary save" data-action="save-entry" ${!e||(!items.length&&!packs.length)||!activeShifts().length?'disabled':''}>${icon('check')} Uložit a další zaměstnanec ${icon('arrow')}</button><p class="shortcut"><span class="shortkey">Ctrl</span> + <span class="shortkey">Enter</span> pro rychlé uložení</p>`;}
function cartRow(i,type){return`<div class="cartrow"><div class="name">${esc(i.name)}${type==='pack'?`<small>${esc(payerLabel(i.payer))}</small>`:''}<div class="qty"><button data-qty="${i.id}" data-kind="${type}" data-delta="-1" aria-label="Odebrat ${esc(i.name)}">−</button><span>${i.qty}×</span><button data-qty="${i.id}" data-kind="${type}" data-delta="1" aria-label="Přidat ${esc(i.name)}">+</button></div></div><b>${money(i.price*i.qty)}</b></div>`;}
function refreshCart(){if(page!=='entry')return;$('#foods').innerHTML=foodCards();$('#packgrid').innerHTML=packButtons();$('#summary-inner').innerHTML=summary();$('#mobile-entrybar').innerHTML=mobileBar();}
function bindEntryInputs(){if(page!=='entry')return;$('#employee-search')?.addEventListener('input',e=>{employeeQuery=e.target.value;$('#employee-picker').innerHTML=employeeChips();});$('#food-search')?.addEventListener('input',e=>{foodQuery=e.target.value;$('#foods').innerHTML=foodCards();});$('#shift-select')?.addEventListener('change',e=>{selectedShift=e.target.value;refreshCart();});$('#entrydate')?.addEventListener('change',e=>{if(!validDate(e.target.value))return;selectedDate=e.target.value;render();});}
function validDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(new Date(d+'T12:00:00').getTime());}
async function saveEntry(){if(!canWrite())return toast('Nemáte oprávnění k zápisu.');if(!selectedEmployee||!employee(selectedEmployee)?.active||(!pickedItems().length&&!pickedPacks().length))return toast('Vyberte zaměstnance a alespoň jednu položku.');const old=findDaily();if(old?.paid)return toast('Tento den už je vyúčtovaný. Administrátor musí nejprve zrušit označení úhrady.');const r={...projected(),id:old?.id||uid(),paid:false,createdBy:old?.createdBy||actorName(),updatedAt:new Date().toISOString()};const name=full(employee(selectedEmployee));if(await change(s=>{const i=s.records.findIndex(x=>x.id===r.id);i>=0?s.records[i]=r:s.records.push(r);},audit(old?'Doplnění denního zápisu':'Vytvoření zápisu',name,old?describe(old):'Žádný zápis',describe(r)))){cart={};packcart={};selectedEmployee='';employeeQuery='';foodQuery='';render();$('#employee-search')?.focus();toast('Uloženo pro '+name+'. Můžete zapsat dalšího.');}}
function recordsTable(rs,opts={}){if(!rs.length)return`<div class="empty"><strong>Zatím žádné zápisy</strong>${page==='entry'?'Vyberte zaměstnance a přidejte první jídlo.':'Pro vybrané období nejsou záznamy.'}</div>`;return`<div class="tablewrap"><table><thead><tr><th>Zaměstnanec</th>${opts.date?'<th>Datum</th>':''}<th>Směna</th><th>Jídla a obaly</th><th>Cena jídel</th><th>Obaly</th><th>Doplatek</th><th>Stav</th>${canWrite()?'<th></th>':''}</tr></thead><tbody>${rs.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>{const e=employee(r.employeeId),c=calc(r);return`<tr><td><div class="personcell"><span class="avatar ${r.employeeId==='e0'?'green':''}">${esc(initials(full(e)))}</span><div><strong>${esc(full(e))}</strong><small>${esc(e?.position)}</small></div></div></td>${opts.date?`<td>${esc(fmtDate(r.date))}</td>`:''}<td><span class="badge">${esc(r.shift.code)}</span></td><td style="white-space:normal;min-width:180px;max-width:320px;line-height:1.8">${esc(r.items.map(i=>i.qty+'× '+i.name).join(', '))}${r.packs.length?`<div class="muted" style="font-size:9px">${esc(r.packs.map(p=>p.qty+'× '+p.name).join(', '))}</div>`:''}</td><td>${money(c.meals)}</td><td>${money(c.packs)}</td><td class="money ${c.due?'orange':''}">${money(c.due)}</td><td>${r.paid?'<span class="badge green">Uhrazeno</span>':c.due?'<span class="badge orange">K úhradě</span>':'<span class="badge">Bez doplatku</span>'}</td>${canWrite()?`<td><div class="actions"><button class="iconbutton" data-edit-record="${r.id}" title="Upravit zápis" aria-label="Upravit zápis pro ${esc(full(e))}">${icon('edit')}</button>${isAdmin()?`<button class="iconbutton" data-toggle-paid="${r.id}" title="${r.paid?'Zrušit úhradu':'Označit uhrazeno'}" aria-label="${r.paid?'Zrušit úhradu':'Označit uhrazeno'}">${icon('check')}</button><button class="iconbutton" data-delete-record="${r.id}" title="Odstranit zápis" aria-label="Odstranit zápis">${icon('trash')}</button>`:''}</div></td>`:''}</tr>`;}).join('')}</tbody></table></div>`;}
function employeesPage(){const es=state.employees.filter(e=>norm(full(e)+' '+e.position).includes(norm(listQuery)));return heading(`<button class="btn primary" data-action="add-employee">${icon('plus')} Přidat zaměstnance</button>`)+`<div class="filterline"><div class="searchwrap search-wide">${icon('search')}<input class="search" id="list-search" placeholder="Hledat zaměstnance…" value="${esc(listQuery)}"></div><span class="muted" style="font-size:11px">${activeEmployees().length} aktivních zaměstnanců</span></div><div class="panel"><div class="panelhead"><h2>${icon('users')} Váš tým</h2><span class="eyebrow">Oprávnění mění pouze administrátor</span></div><div class="list" id="employee-list">${employeeList(es)}</div></div><div class="info" style="margin-top:20px">${icon('shield')} Pověřený zaměstnanec může zapisovat a upravovat stravu za ostatní. Nemůže měnit ceny, oprávnění, označovat úhrady ani mazat záznamy. Každá jeho změna se zapíše do historie.</div>`;}
function employeeList(es){return es.map(e=>`<div class="listrow"><span class="avatar green">${esc(initials(full(e)))}</span><div class="grow"><strong>${esc(full(e))} ${!e.active?'<span class="badge orange">Archivováno</span>':''}</strong><small>${esc(e.position)} · @${esc(e.username)}</small></div><label class="permission-label">Může zapisovat<button class="pill-switch ${e.writer?'on':''}" data-permission="${e.id}" role="switch" aria-checked="${!!e.writer}" aria-label="Povolit zápis pro ${esc(full(e))}" ${!e.active?'disabled':''}></button></label><button class="iconbutton" data-edit-employee="${e.id}" aria-label="Upravit ${esc(full(e))}">${icon('edit')}</button><button class="iconbutton" data-archive-employee="${e.id}" title="${e.active?'Archivovat':'Obnovit'}" aria-label="${e.active?'Archivovat':'Obnovit'} ${esc(full(e))}">${icon(e.active?'trash':'plus')}</button></div>`).join('')||'<div class="empty">Žádný zaměstnanec neodpovídá hledání.</div>';}
function employeeModal(id){if(!isAdmin())return;const e=employee(id)||{};showModal(id?'Upravit zaměstnance':'Nový zaměstnanec',`<form id="employee-form" class="modalform" data-id="${id||''}"><div class="formrow">${field('Jméno',input('first',e.first||'','text','required maxlength="60" autocomplete="off"'))}${field('Příjmení',input('last',e.last||'','text','required maxlength="60"'))}</div>${field('Pracovní pozice',`<input name="position" list="positions-list" value="${esc(e.position)}" required maxlength="60"><datalist id="positions-list">${state.positions.map(p=>`<option value="${esc(p)}">`).join('')}</datalist>`)}${field('Uživatelské jméno',input('username',e.username||'','text','required maxlength="50" pattern="[a-zA-Z0-9._-]+" title="Písmena bez diakritiky, čísla, tečka, pomlčka nebo podtržítko"'))}<label class="checkfield"><input type="checkbox" name="writer" ${e.writer?'checked':''}> Může zapisovat stravu za celou směnu</label>${field(id?'Nové heslo (prázdné = ponechat původní)':'Přístupové heslo',input('password','','password',`${id?'':'required'} minlength="12" maxlength="128" autocomplete="new-password"`))}<div class="info">Heslo musí mít alespoň 12 znaků. Zaměstnanec se přihlásí svým uživatelským jménem a může si heslo změnit. Změnou hesla zrušíte jeho dosavadní přihlášení.</div><div class="modalfooter"><button type="button" class="btn" data-action="close-modal">Zrušit</button><button class="btn primary">${icon('check')} Uložit zaměstnance</button></div></form>`);}
function menuPage(){return heading(`<button class="btn" data-action="add-category">${icon('plus')} Kategorie</button><button class="btn primary" data-action="add-food">${icon('plus')} Přidat jídlo</button>`)+`<div class="panel"><div class="panelhead"><h2>${icon('food')} Jídelníček</h2><span class="eyebrow">${activeFoods().length} aktivních jídel</span></div><div class="pad"><div class="tabs">${['Vše',...state.categories].map(c=>`<button class="tab ${category===c?'active':''}" data-menu-category="${esc(c)}">${esc(c)}</button>`).join('')}</div>${category!=='Vše'&&state.categories.includes(category)?`<button class="btn" data-remove-category="${esc(category)}" style="margin:5px 0 12px">${icon('trash')} Odebrat prázdnou kategorii</button>`:''}<div class="list">${activeFoods().filter(f=>category==='Vše'||category==='Oblíbené'||category===f.category).map(f=>`<div class="listrow"><button class="iconbutton" data-favorite="${f.id}" style="color:${f.favorite?'#b1a052':'#b5bdae'}" title="${f.favorite?'Odebrat z oblíbených':'Přidat mezi oblíbené'}" aria-label="Změnit oblíbenost ${esc(f.name)}"><span style="font-size:20px">${f.favorite?'★':'☆'}</span></button><div class="grow"><strong>${esc(f.name)}</strong><small>${esc(f.category)}</small></div><b class="money">${money(f.price)}</b><button class="iconbutton" data-edit-food="${f.id}" aria-label="Upravit ${esc(f.name)}">${icon('edit')}</button><button class="iconbutton" data-remove-food="${f.id}" aria-label="Archivovat ${esc(f.name)}">${icon('trash')}</button></div>`).join('')||'<div class="empty">Tato kategorie zatím nemá žádná jídla.</div>'}</div></div></div><div class="info" style="margin-top:20px">Hvězdičkou označte nejčastější personální jídla. V rychlém zápisu se zobrazí jako první. Změny cen platí pro nové položky; historie si uchovává původní cenu.</div>`;}
function foodModal(id){if(!isAdmin())return;const f=state.foods.find(f=>f.id===id)||{};if(!state.categories.length)return toast('Nejdřív vytvořte kategorii jídel.');showModal(id?'Upravit jídlo':'Nové jídlo',`<form id="food-form" class="modalform" data-id="${id||''}">${field('Název pokrmu',input('name',f.name||'','text','required maxlength="100"'))}<div class="formrow">${field('Cena v Kč',input('price',f.price??'','number','required min="0" max="100000" step="0.01"'))}${field('Kategorie',`<select name="category">${state.categories.map(c=>option(c,c,f.category||state.categories[0])).join('')}</select>`)}</div><label class="checkfield"><input type="checkbox" name="favorite" ${f.favorite?'checked':''}> Oblíbené — zobrazit v rychlém zápisu</label><div class="modalfooter"><button type="button" class="btn" data-action="close-modal">Zrušit</button><button class="btn primary">Uložit jídlo</button></div></form>`);}
function reportsPage(){const rs=state.records.filter(r=>r.date.startsWith(month));const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate();if(!reportDate.startsWith(month))reportDate=month+'-01';const daily=rs.filter(r=>r.date===reportDate);return heading(`<input type="month" id="report-month" class="months" value="${month}" aria-label="Měsíc přehledu"><button class="btn" data-action="export">${icon('download')} Export CSV</button>`)+stats(rs)+`<div class="panel"><div class="panelhead"><h2>${new Date(month+'-01T12:00:00').toLocaleDateString('cs-CZ',{month:'long',year:'numeric'})}</h2><span class="eyebrow">${rs.length} denních zápisů</span></div><div class="day-tabs">${Array.from({length:days},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0');return`<button class="day ${reportDate===d?'active':''}" data-report-date="${d}" title="${fmtDate(d)}"><span>${new Date(d+'T12:00:00').toLocaleDateString('cs-CZ',{weekday:'short'})}</span><b>${i+1}</b>${rs.some(r=>r.date===d)?'<span style="margin:5px 0 0">•</span>':'<span style="margin:5px 0 0">&nbsp;</span>'}</button>`;}).join('')}</div><div class="panelhead"><h2 style="font-size:13px">${fmtDate(reportDate)}</h2><span class="eyebrow">Doplatky: ${money(sum(daily,'due'))}</span></div>${recordsTable(daily)}</div><div class="panel daily"><div class="panelhead"><h2>Vyúčtování zaměstnanců za měsíc</h2><span class="eyebrow">Neuhrazeno: ${money(sum(rs.filter(r=>!r.paid),'due'))}</span></div><div class="tablewrap"><table><thead><tr><th>Zaměstnanec</th><th>Zapsaných dnů</th><th>Cena jídel</th><th>Doplatek celkem</th><th>Zbývá uhradit</th></tr></thead><tbody>${state.employees.filter(e=>rs.some(r=>r.employeeId===e.id)).map(e=>{const rr=rs.filter(r=>r.employeeId===e.id);return`<tr><td>${esc(full(e))}</td><td>${rr.length}</td><td>${money(sum(rr,'meals'))}</td><td>${money(sum(rr,'due'))}</td><td class="money orange">${money(sum(rr.filter(r=>!r.paid),'due'))}</td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">Žádné zápisy v tomto měsíci.</td></tr>'}</tbody></table></div></div>`;}
function profilePage(){const id=isAdmin()?profileId:actor.id,e=employee(id)||state.employees[0];if(!e)return heading()+`<div class="empty">Nejdřív přidejte zaměstnance.</div>`;const rs=state.records.filter(r=>r.employeeId===e.id&&r.date.startsWith(month)),all=state.records.filter(r=>r.employeeId===e.id);const counts={};rs.forEach(r=>r.items.forEach(i=>{counts[i.name]=(counts[i.name]||0)+i.qty;}));const ranks=Object.entries(counts).sort((a,b)=>b[1]-a[1]);return heading(`<input type="month" id="profile-month" class="months" value="${month}" aria-label="Měsíc osobního přehledu">`)+`<div class="profile-banner"><span class="avatar">${esc(initials(full(e)))}</span><div><h2>${esc(full(e))}</h2><p>${esc(e.position)} · ${rs.length} zapsaných dnů v měsíci</p></div>${isAdmin()?`<select id="profile-select" class="profile-select" aria-label="Profil zaměstnance">${state.employees.map(x=>option(x.id,full(x),e.id)).join('')}</select>`:''}<div class="right"><small>Zbývá uhradit tento měsíc</small><strong>${money(sum(rs.filter(r=>!r.paid),'due'))}</strong></div></div>${isAdmin()&&e.active?`<div class="info" style="display:flex;align-items:center;gap:12px;margin-bottom:20px"><span style="flex:1">${icon('shield')} <b>Pověření k zápisu za směnu</b><br>Tento zaměstnanec může zapisovat jídla za ostatní. Všechny jeho změny se evidují v historii.</span><button class="pill-switch ${e.writer?'on':''}" data-permission="${e.id}" role="switch" aria-checked="${e.writer}" aria-label="Povolit zápis pro ${esc(full(e))}"></button></div>`:''}<div class="stats">${stat('Odebrané porce',rs.reduce((a,r)=>a+r.items.reduce((n,i)=>n+i.qty,0),0),'za vybraný měsíc','food')}${stat('Využitý příspěvek',money(sum(rs,'covered')),'hrazeno z limitů směn','shield')}${stat('Doplatek celkem',money(sum(rs,'due')),'včetně již uhrazených částek','chart')}${stat('Již uhrazeno',money(sum(rs.filter(r=>r.paid),'due')),'za vybraný měsíc','check',true)}</div><div class="section-layout"><div class="panel"><div class="panelhead"><h2>${icon('star')} Nejčastější jídla</h2><span class="eyebrow">Vybraný měsíc</span></div><div class="pad">${ranks.length?ranks.slice(0,6).map(([n,q],i)=>`<div class="rank"><span class="num">0${i+1}</span><div class="grow">${esc(n)}<div class="bar"><span style="width:${q/ranks[0][1]*100}%"></span></div></div><b>${q}×</b></div>`).join(''):'<div class="empty">Po prvním zápisu se tady objeví oblíbená jídla.</div>'}</div></div><div class="panel"><div class="panelhead"><h2>${icon('chart')} Ještě pár čísel</h2></div><div class="pad"><div class="listrow"><div class="grow"><strong>Průměrná cena jídel za den</strong><small>Ve vybraném měsíci</small></div><b class="money">${money(rs.length?sum(rs,'meals')/rs.length:0)}</b></div><div class="listrow"><div class="grow"><strong>Obaly hrazené zaměstnancem</strong><small>Vždy mimo příspěvek</small></div><b class="money">${money(sum(rs,'own'))}</b></div><div class="listrow"><div class="grow"><strong>Dny bez doplatku</strong><small>Ve vybraném měsíci</small></div><b class="money">${rs.filter(r=>!calc(r).due).length} / ${rs.length}</b></div><div class="listrow"><div class="grow"><strong>Celkem zapsaných dnů</strong><small>Za celou historii</small></div><b class="money">${all.length}</b></div></div></div></div><div class="panel daily"><div class="panelhead"><h2>Historie stravování</h2><span class="eyebrow">${new Date(month+'-01T12:00:00').toLocaleDateString('cs-CZ',{month:'long',year:'numeric'})}</span></div>${recordsTable(rs,{date:true})}</div>`;}
function auditPage(){return heading()+`<div class="info" style="margin-bottom:20px">${icon('shield')} Historie se vytváří na serveru pod přihlášeným účtem. Zobrazuje posledních 2 000 událostí; starší zůstávají zachované v databázi. Uložené události nelze z aplikace změnit ani odstranit.</div><div class="panel"><div class="panelhead"><h2>${icon('clock')} Všechny změny</h2><span class="eyebrow">${state.audit.length} událostí</span></div>${state.audit.map(a=>`<div class="audititem"><span class="audit-icon">${icon('clock')}</span><div style="flex:1;min-width:0"><h3>${esc(a.action)} <span class="muted">· ${esc(a.target)}</span></h3><p><strong>${esc(a.actor)}</strong> · ${new Date(a.at).toLocaleString('cs-CZ')}</p>${a.before?`<div class="auditdiff"><span><b>Před:</b> ${esc(a.before)}</span></div>`:''}${a.after?`<div class="auditdiff"><span><b>Po:</b> ${esc(a.after)}</span></div>`:''}</div></div>`).join('')}</div>`;}
function settingsPage(){return heading()+`<div class="section-layout"><div class="stack"><section class="panel"><div class="panelhead"><h2>${icon('clock')} Směny a příspěvky</h2><button class="btn light" data-action="add-shift">${icon('plus')} Směna</button></div><div class="list">${activeShifts().map(s=>`<div class="listrow"><span class="badge">${esc(s.code)}</span><div class="grow"><strong>${esc(s.name)}</strong><small>Limit na zaměstnance a den</small></div><b class="settings-value">${money(s.limit)}</b><button class="iconbutton" data-edit-shift="${s.id}" aria-label="Upravit směnu ${esc(s.name)}">${icon('edit')}</button><button class="iconbutton" data-remove-shift="${s.id}" aria-label="Archivovat směnu ${esc(s.name)}">${icon('trash')}</button></div>`).join('')||'<div class="empty">Přidejte první směnu.</div>'}</div></section><section class="panel"><div class="panelhead"><h2>${icon('box')} Obaly a jejich úhrada</h2><button class="btn light" data-action="add-pack">${icon('plus')} Obal</button></div><div class="list">${activePacks().map(p=>`<div class="listrow"><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(payerLabel(p.payer))}</small></div><b class="settings-value">${money(p.price)}</b><button class="iconbutton" data-edit-pack="${p.id}" aria-label="Upravit obal ${esc(p.name)}">${icon('edit')}</button><button class="iconbutton" data-remove-pack="${p.id}" aria-label="Archivovat obal ${esc(p.name)}">${icon('trash')}</button></div>`).join('')||'<div class="empty">Nejsou nastavené žádné obaly.</div>'}</div></section></div><div class="stack"><section class="panel"><div class="panelhead"><h2>${icon('users')} Pracovní pozice</h2><button class="iconbutton" data-action="add-position" aria-label="Přidat pozici">${icon('plus')}</button></div><div class="list">${state.positions.map(p=>`<div class="listrow"><span class="grow" style="font-size:12px">${esc(p)}</span><button class="iconbutton" data-remove-position="${esc(p)}" aria-label="Odebrat pozici ${esc(p)}">${icon('trash')}</button></div>`).join('')}</div></section><div class="info"><b>Jak se počítá doplatek?</b><br>Jídla a obaly hrazené z rozpočtu čerpají společný limit směny. Zaměstnanec doplácí překročení limitu a vždy celou cenu obalů označených „hradí zaměstnanec“. Obaly hrazené podnikem limit nečerpají.<br><br>Ceny i pravidla uloženého zápisu zůstávají zachované při pozdější změně nastavení.</div></div></div>`;}
function configModal(type,id){if(!isAdmin())return;const pack=type==='pack',obj=(pack?state.packs:state.shifts).find(x=>x.id===id)||{};showModal((id?'Upravit ':'Nová ')+(pack?'obal':'směna'),`<form id="config-form" class="modalform" data-kind="${type}" data-id="${id||''}">${field('Název',input('name',obj.name||'','text','required maxlength="70"'))}${!pack?field('Zkratka směny',input('code',obj.code||'','text','required maxlength="8"')):''}${field(pack?'Cena obalu v Kč':'Denní příspěvek v Kč',input('amount',pack?obj.price??'':obj.limit??'','number','required min="0" max="100000" step="0.01"'))}${pack?field('Kdo hradí obal',`<select name="payer">${option('company','Hradí podnik — mimo limit',obj.payer)}${option('budget','Čerpá limit směny',obj.payer)}${option('employee','Hradí zaměstnanec — vždy doplácí',obj.payer)}</select>`):''}<div class="modalfooter"><button type="button" class="btn" data-action="close-modal">Zrušit</button><button class="btn primary">Uložit</button></div></form>`);}
function simpleModal(kind,title){showModal(title,`<form id="simple-form" class="modalform" data-kind="${kind}">${field('Název',input('name','','text','required maxlength="60"'))}<div class="modalfooter"><button type="button" class="btn" data-action="close-modal">Zrušit</button><button class="btn primary">Přidat</button></div></form>`);}
function confirmModal(title,text,action,id){showModal(title,`<div class="modalform"><p style="font-size:12px;line-height:1.8">${esc(text)}</p><div class="modalfooter"><button class="btn" data-action="close-modal">Zrušit</button><button class="btn primary" data-confirm="${action}" data-id="${esc(id)}">Potvrdit</button></div></div>`);}
function editRecord(id){if(!canWrite())return;const r=state.records.find(r=>r.id===id);if(!r)return;if(r.paid)return toast('Zápis je uhrazený. Nejprve požádejte admina o zrušení úhrady.');editId=id;showModal('Upravit denní zápis',`<form id="record-form" class="modalform" data-id="${r.id}"><div class="info"><b>${esc(full(employee(r.employeeId)))}</b> · ${fmtDate(r.date)} · ${esc(r.shift.code)} · limit ${money(r.shift.limit)}<br>Upravte počty. Hodnota 0 položku odstraní. Pro přidání jídla použijte rychlý zápis se stejným dnem a zaměstnancem.</div>${r.items.map((i,n)=>field(i.name+' · '+money(i.price),input('item-'+n,i.qty,'number','required min="0" max="100" step="1"'))).join('')}${r.packs.map((i,n)=>field(i.name+' · '+money(i.price)+' · '+payerLabel(i.payer),input('pack-'+n,i.qty,'number','required min="0" max="100" step="1"'))).join('')}<div class="modalfooter"><button type="button" class="btn" data-action="close-modal">Zrušit</button><button class="btn primary">Uložit změny</button></div></form>`);}
function exportCSV(){if(!isAdmin())return;const rs=state.records.filter(r=>r.date.startsWith(month));const rows=[['Datum','Zaměstnanec','Směna','Limit','Jídla','Cena jídel','Cena obalů','Čerpání příspěvku','Doplatek','Stav','Autor zápisu'],...rs.map(r=>{const c=calc(r);return[r.date,full(employee(r.employeeId)),r.shift.code,r.shift.limit,r.items.map(i=>i.qty+'× '+i.name).join(', '),c.meals,c.packs,c.covered,c.due,r.paid?'Uhrazeno':'Neuhrazeno',r.createdBy];})];const safe=v=>{let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='perso-'+month+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Měsíční přehled byl exportován.');}
function onlyAdmin(){if(!isAdmin()){toast('Tuto akci může provést pouze administrátor.');return false;}return true;}
function numberOK(v,integer=false){return Number.isFinite(v)&&v>=0&&v<=100000&&(!integer||Number.isInteger(v));}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('button,a[data-nav]');if(!b)return;
 if(b.dataset.nav){ev.preventDefault();const next=b.dataset.nav;if(Object.keys(cart).some(k=>cart[k])||Object.keys(packcart).some(k=>packcart[k])){if(next!=='entry')toast('Rozpracovaný výběr zůstává v rychlém zápisu.');}page=next;listQuery='';if(page==='menu')category='Vše';render();window.scrollTo(0,0);return;}
 if(b.dataset.employee){selectedEmployee=b.dataset.employee;const r=findDaily();if(r)selectedShift=r.shift.id;render();return;}
 if(b.dataset.food){const id=b.dataset.food;cart[id]=Math.min(100,(cart[id]||0)+1);refreshCart();return;}
 if(b.dataset.pack){const id=b.dataset.pack;packcart[id]=Math.min(100,(packcart[id]||0)+1);refreshCart();return;}
 if(b.dataset.qty){const dict=b.dataset.kind==='food'?cart:packcart,id=b.dataset.qty;dict[id]=Math.max(0,Math.min(100,(dict[id]||0)+Number(b.dataset.delta)));refreshCart();return;}
 if(b.dataset.category){category=b.dataset.category;$('#food-tabs').innerHTML=foodTabs();$('#foods').innerHTML=foodCards();return;}
 if(b.dataset.menuCategory){category=b.dataset.menuCategory;render();return;}
 if(b.dataset.reportDate){reportDate=b.dataset.reportDate;render();return;}
 if(b.dataset.editEmployee){employeeModal(b.dataset.editEmployee);return;}
 if(b.dataset.permission){if(!onlyAdmin())return;const e=employee(b.dataset.permission);if(!e?.active)return;const grant=!e.writer;if(await change(s=>s.employees.find(x=>x.id===e.id).writer=grant,audit(grant?'Povolení zápisu za směnu':'Odebrání oprávnění k zápisu',full(e),'Může zapisovat: '+(e.writer?'ano':'ne'),'Může zapisovat: '+(grant?'ano':'ne')))){render();toast(grant?full(e)+' může zapisovat za směnu.':'Oprávnění k zápisu bylo odebráno.');}return;}
 if(b.dataset.archiveEmployee){if(!onlyAdmin())return;const e=employee(b.dataset.archiveEmployee);confirmModal(e.active?'Archivovat zaměstnance?':'Obnovit zaměstnance?',e.active?'Historie zůstane zachovaná. Profil nebude dostupný pro nové zápisy.':'Zaměstnanec se znovu zobrazí ve výběru. Oprávnění k zápisu můžete nastavit zvlášť.','archiveEmployee',e.id);return;}
 if(b.dataset.editFood){foodModal(b.dataset.editFood);return;}
 if(b.dataset.favorite){if(!onlyAdmin())return;const f=state.foods.find(f=>f.id===b.dataset.favorite);if(await change(s=>s.foods.find(x=>x.id===f.id).favorite=!f.favorite,audit('Změna oblíbeného jídla',f.name,f.favorite?'Oblíbené':'Běžné',f.favorite?'Běžné':'Oblíbené')))render();return;}
 if(b.dataset.removeFood){if(!onlyAdmin())return;confirmModal('Archivovat jídlo?','Jídlo zmizí z nabídky pro nové zápisy. Dosavadní záznamy zůstanou beze změny.','removeFood',b.dataset.removeFood);return;}
 if(b.dataset.removeCategory){if(!onlyAdmin())return;const c=b.dataset.removeCategory;if(activeFoods().some(f=>f.category===c))return toast('Kategorie obsahuje jídla. Nejprve je přesuňte nebo archivujte.');confirmModal('Odebrat kategorii?',c,'removeCategory',c);return;}
 if(b.dataset.editShift){configModal('shift',b.dataset.editShift);return;}
 if(b.dataset.editPack){configModal('pack',b.dataset.editPack);return;}
 if(b.dataset.removeShift){if(!onlyAdmin())return;if(activeShifts().length<=1)return toast('Alespoň jedna směna musí zůstat aktivní.');confirmModal('Archivovat směnu?','Původní příspěvky v historii se nezmění.','removeShift',b.dataset.removeShift);return;}
 if(b.dataset.removePack){if(!onlyAdmin())return;confirmModal('Archivovat obal?','Obal nebude dostupný pro nové zápisy. Historie zůstane zachovaná.','removePack',b.dataset.removePack);return;}
 if(b.dataset.removePosition){if(!onlyAdmin())return;const p=b.dataset.removePosition;if(state.employees.some(e=>e.active&&e.position===p))return toast('Pozici používá aktivní zaměstnanec. Nejprve mu změňte pozici.');confirmModal('Odebrat pozici?',p,'removePosition',p);return;}
 if(b.dataset.editRecord){editRecord(b.dataset.editRecord);return;}
 if(b.dataset.deleteRecord){if(!onlyAdmin())return;const r=state.records.find(r=>r.id===b.dataset.deleteRecord);if(r.paid)return toast('Nejdřív zrušte označení úhrady.');confirmModal('Odstranit zápis?',full(employee(r.employeeId))+' · '+fmtDate(r.date)+'. Odstranění včetně původních hodnot zůstane v historii změn.','deleteRecord',r.id);return;}
 if(b.dataset.togglePaid){if(!onlyAdmin())return;const r=state.records.find(r=>r.id===b.dataset.togglePaid);if(!calc(r).due)return toast('Tento zápis nemá doplatek k úhradě.');if(await change(s=>s.records.find(x=>x.id===r.id).paid=!r.paid,audit(r.paid?'Zrušení úhrady':'Označení úhrady',full(employee(r.employeeId))+' · '+fmtDate(r.date),r.paid?'Uhrazeno':'Neuhrazeno',!r.paid?'Uhrazeno':'Neuhrazeno'))){render();toast(r.paid?'Úhrada byla zrušena.':'Doplatek označen jako uhrazený.');}return;}
 if(b.dataset.confirm){if(!onlyAdmin())return;const id=b.dataset.id,action=b.dataset.confirm;let log,mut;
 if(action==='archiveEmployee'){const e=employee(id);const was=e.active;log=audit(was?'Archivace zaměstnance':'Obnovení zaměstnance',full(e),was?'Aktivní':'Archivováno',was?'Archivováno · oprávnění k zápisu odebráno':'Aktivní · bez oprávnění k zápisu');mut=s=>{const x=s.employees.find(x=>x.id===id);x.active=!was;x.writer=false;};}
 if(action==='removeFood'){const f=state.foods.find(f=>f.id===id);log=audit('Archivace jídla',f.name,money(f.price),'Archivováno');mut=s=>s.foods.find(f=>f.id===id).active=false;}
 if(action==='removeCategory'){log=audit('Odebrání kategorie',id,id,'Odebráno');mut=s=>s.categories=s.categories.filter(c=>c!==id);category='Vše';}
 if(action==='removePosition'){log=audit('Odebrání pracovní pozice',id,id,'Odebráno');mut=s=>s.positions=s.positions.filter(c=>c!==id);}
 if(action==='removeShift'){const x=state.shifts.find(x=>x.id===id);log=audit('Archivace směny',x.name,x.code+' · '+money(x.limit),'Archivováno');mut=s=>s.shifts.find(x=>x.id===id).active=false;}
 if(action==='removePack'){const x=state.packs.find(x=>x.id===id);log=audit('Archivace obalu',x.name,money(x.price)+' · '+payerLabel(x.payer),'Archivováno');mut=s=>s.packs.find(x=>x.id===id).active=false;}
 if(action==='deleteRecord'){const r=state.records.find(x=>x.id===id);log=audit('Odstranění zápisu',full(employee(r.employeeId)),describe(r),'Odstraněno');mut=s=>s.records=s.records.filter(x=>x.id!==id);}
 if(mut&&await change(mut,log)){closeModal();if(!activeShifts().some(x=>x.id===selectedShift))selectedShift=activeShifts()[0]?.id;for(const id of Object.keys(cart))if(!activeFoods().some(f=>f.id===id))delete cart[id];for(const id of Object.keys(packcart))if(!activePacks().some(p=>p.id===id))delete packcart[id];render();toast('Změna uložena a zaznamenána do historie.');}return;}
 switch(b.dataset.action){case'toggle-menu':$('.shell').classList.toggle('menuopen');break;case'logout':if(Object.values(cart).some(Boolean)||Object.values(packcart).some(Boolean)){showModal('Odhlásit se?',`<div class="modalform"><p>Rozpracovaný výběr ještě není uložený. Chcete se odhlásit?</p><div class="modalfooter"><button class="btn" data-action="close-modal">Zpět</button><button class="btn primary" data-action="confirm-logout">Odhlásit se</button></div></div>`);}else await doLogout();break;case'confirm-logout':closeModal();await doLogout();break;case'password':passwordModal();break;case'close-modal':closeModal();break;case'save-entry':saveEntry();break;case'today':selectedDate=now;render();break;case'add-employee':employeeModal();break;case'add-food':foodModal();break;case'add-category':if(onlyAdmin())simpleModal('category','Nová kategorie');break;case'add-position':if(onlyAdmin())simpleModal('position','Nová pracovní pozice');break;case'add-shift':configModal('shift');break;case'add-pack':configModal('pack');break;case'export':exportCSV();break;}
});
document.addEventListener('submit',async ev=>{
 const form=ev.target;if(!form.id)return;ev.preventDefault();const fd=new FormData(form),val=k=>String(fd.get(k)||'').trim();
 if(form.id==='setup-form'||form.id==='loginform'){const btn=form.querySelector('button[type="submit"]');btn.disabled=true;try{if(form.id==='setup-form'){if(fd.get('password')!==fd.get('confirm'))throw new Error('Zadaná hesla se neshodují.');await api('/api/setup',{token:setupSecret,name:val('name'),password:fd.get('password')});setupSecret='';setupRequired=false;}else await api('/api/login',{username:val('username'),password:fd.get('password')});page='entry';await loadSession();}catch(e){toast(e.message);btn.disabled=false;}return;}
 if(form.id==='password-form'){const password=fd.get('password');if(password!==fd.get('confirm'))return toast('Zadaná hesla se neshodují.');try{await api('/api/password',{currentPassword:fd.get('currentPassword'),password});closeModal();toast('Heslo bylo změněno. Ostatní přihlášení jsou zrušena.');}catch(e){toast(e.message);}return;}
 if(form.id==='employee-form'){if(!onlyAdmin())return;const id=form.dataset.id,old=employee(id);const username=val('username');if(state.employees.some(e=>e.id!==id&&e.username.toLowerCase()===username.toLowerCase()))return toast('Uživatelské jméno už existuje.');const obj={id:id||uid(),first:val('first'),last:val('last'),position:val('position'),username,writer:fd.has('writer'),active:old?.active??true};if(!obj.first||!obj.last||!obj.position||!username)return toast('Vyplňte všechna pole.');const desc=e=>e?`${full(e)} · ${e.position} · @${e.username} · může zapisovat: ${e.writer?'ano':'ne'}`:'Žádný profil';if(await change(s=>{const i=s.employees.findIndex(e=>e.id===obj.id);if(i>=0)s.employees[i]=obj;else s.employees.push(obj);if(!s.positions.includes(obj.position))s.positions.push(obj.position);},audit(id?'Úprava zaměstnance':'Vytvoření zaměstnance',full(obj),desc(old),desc(obj)),fd.get('password')?{employeeId:obj.id,password:fd.get('password')}:undefined)){closeModal();render();toast('Zaměstnanec uložen.');}return;}
 if(form.id==='food-form'){if(!onlyAdmin())return;const id=form.dataset.id,old=state.foods.find(f=>f.id===id),price=Number(val('price'));if(!val('name')||!numberOK(price)||!state.categories.includes(val('category')))return toast('Zkontrolujte název, kategorii a cenu.');const obj={id:id||uid(),name:val('name'),price,category:val('category'),favorite:fd.has('favorite'),active:true},desc=f=>f?`${f.name} · ${money(f.price)} · ${f.category} · oblíbené: ${f.favorite?'ano':'ne'}`:'Žádné jídlo';if(await change(s=>{const i=s.foods.findIndex(f=>f.id===obj.id);i>=0?s.foods[i]=obj:s.foods.push(obj);},audit(id?'Úprava jídla':'Nové jídlo',obj.name,desc(old),desc(obj)))){closeModal();render();toast('Jídlo uloženo.');}return;}
 if(form.id==='simple-form'){if(!onlyAdmin())return;const pack=form.dataset.kind==='category',key=pack?'categories':'positions',name=val('name');if(!name)return;if(state[key].some(x=>norm(x)===norm(name)))return toast('Tento název už existuje.');if(await change(s=>s[key].push(name),audit(pack?'Nová kategorie':'Nová pracovní pozice',name,'',name))){closeModal();render();toast('Přidáno.');}return;}
 if(form.id==='config-form'){if(!onlyAdmin())return;const pack=form.dataset.kind==='pack',key=pack?'packs':'shifts',id=form.dataset.id,old=state[key].find(x=>x.id===id),amount=Number(val('amount'));if(!val('name')||!numberOK(amount))return toast('Zkontrolujte název a částku.');const obj={id:id||uid(),name:val('name'),active:true,...(pack?{price:amount,payer:val('payer')}:{code:val('code'),limit:amount})};if(pack&&!['employee','company','budget'].includes(obj.payer))return;if(!pack&&!obj.code)return toast('Doplňte zkratku směny.');const desc=x=>!x?'Žádná položka':pack?`${x.name} · ${money(x.price)} · ${payerLabel(x.payer)}`:`${x.name} · ${x.code} · ${money(x.limit)}`;if(await change(s=>{const i=s[key].findIndex(x=>x.id===obj.id);i>=0?s[key][i]=obj:s[key].push(obj);},audit((id?'Úprava ':'Vytvoření ')+(pack?'obalu':'směny'),obj.name,desc(old),desc(obj)))){closeModal();render();toast('Nastavení uloženo. Historické zápisy se nemění.');}return;}
 if(form.id==='record-form'){if(!canWrite())return;const old=state.records.find(x=>x.id===form.dataset.id);if(!old||old.paid)return toast('Tento zápis nyní nelze upravit.');const r=structuredClone(old);r.items=r.items.map((i,n)=>({...i,qty:Number(fd.get('item-'+n))})).filter(i=>i.qty!==0);r.packs=r.packs.map((i,n)=>({...i,qty:Number(fd.get('pack-'+n))})).filter(i=>i.qty!==0);if([...r.items,...r.packs].some(i=>!numberOK(i.qty,true)||i.qty>100))return toast('Počet musí být celé číslo od 0 do 100.');if(!r.items.length&&!r.packs.length)return toast('Zápis musí obsahovat alespoň jednu položku. Odstranit celý zápis může administrátor.');r.updatedAt=new Date().toISOString();if(await change(s=>s.records[s.records.findIndex(x=>x.id===r.id)]=r,audit('Úprava denního zápisu',full(employee(r.employeeId)),describe(old),describe(r)))){closeModal();render();toast('Změna uložena, původní hodnoty zůstávají v historii.');}return;}
});
document.addEventListener('change',ev=>{if(ev.target.id==='report-month'||ev.target.id==='profile-month'){if(!/^\d{4}-\d{2}$/.test(ev.target.value))return;month=ev.target.value;render();}if(ev.target.id==='profile-select'){profileId=ev.target.value;render();}});
document.addEventListener('input',ev=>{if(ev.target.id==='list-search'){listQuery=ev.target.value;$('#employee-list').innerHTML=employeeList(state.employees.filter(e=>norm(full(e)+' '+e.position).includes(norm(listQuery))));}});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key==='Enter'&&page==='entry'&&actor&&!$('#modal').open){ev.preventDefault();saveEntry();}});
window.addEventListener('beforeunload',ev=>{if(Object.values(cart).some(Boolean)||Object.values(packcart).some(Boolean)){ev.preventDefault();ev.returnValue='';}});
$('#app').innerHTML='<div class="empty"><strong>Načítám Perso…</strong></div>';
loadSession();
function passwordModal(){showModal('Změnit vlastní heslo',`<form id="password-form" class="modalform">${field('Aktuální heslo',input('currentPassword','','password','required maxlength="128" autocomplete="current-password"'))}${field('Nové heslo',input('password','','password','required minlength="12" maxlength="128" autocomplete="new-password"'))}${field('Zopakovat nové heslo',input('confirm','','password','required minlength="12" maxlength="128" autocomplete="new-password"'))}<div class="modalfooter"><button type="button" class="btn" data-action="close-modal">Zrušit</button><button class="btn primary">Změnit heslo</button></div></form>`);}
function mobileBar(){if(page!=='entry'||!selectedEmployee||(!pickedItems().length&&!pickedPacks().length))return'';return`<div><small>${esc(full(employee(selectedEmployee)))} · doplatek za den</small><strong>${money(calc(projected()).due)}</strong></div><button class="btn primary" data-action="save-entry">${icon('check')} Uložit a další</button>`;}
